const DIGEST=/^[0-9a-f]{64}$/;for(const t of document.querySelectorAll("[data-copy-digest]")){const e=t.parentElement.querySelector("[data-release-digest]"),n=t.parentElement.querySelector(".release-copy-status");if(!e||!n||!DIGEST.test(e.textContent.trim()))continue;t.hidden=!1;const a=t.textContent;let o;t.addEventListener("click",async()=>{const r=e.textContent.trim();try{await navigator.clipboard.writeText(r),t.textContent="Copied",n.textContent="SHA-256 digest copied to the clipboard.",clearTimeout(o),o=setTimeout(()=>{t.textContent=a,n.textContent=""},2e3)}catch{const s=document.createRange();s.selectNodeContents(e);const c=window.getSelection();c.removeAllRanges(),c.addRange(s),n.textContent="Digest selected: press Ctrl+C or Command+C to copy it."}})}
